/**
 * Verified Travelpayouts deep link for https://www.discovercars.com/israel.
 * Generated by the DiscoverCars GitHub Actions workflow with project 406243,
 * partner 622032; do not substitute an untracked direct DiscoverCars link.
 *
 * Travelpayouts explicitly permits adding ?sub_id= to short affiliate URLs:
 * https://support.travelpayouts.com/hc/en-us/articles/12729746524050
 */
export const DISCOVERCARS_ISRAEL_AFFILIATE_URL = "https://discovercars.tpm.li/w2RwEsmb";

/** Preserve an identifiable source page in Travelpayouts reports. */
export function carRentalSubId(sourcePath: string): string {
  const path = (sourcePath.split(/[?#]/, 1)[0] ?? "").replace(/\/+$/, "").toLowerCase();
  // Travel guides have unique slugs; trim their shared prefix for shorter IDs.
  const stem = path.replace(/^\/travel-blog\//, "/").replace(/^\/+/, "");
  const source = stem.replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "") || "home";
  return `itt_car_${source}`;
}

export function carRentalAffiliateUrl(sourcePath: string): string {
  const link = new URL(DISCOVERCARS_ISRAEL_AFFILIATE_URL);
  link.searchParams.set("sub_id", carRentalSubId(sourcePath));
  return link.toString();
}

export function isCarRentalRoute(to: unknown): boolean {
  return to === "/car-rental/" || to === "/car-rental";
}
